from typing import List, Tuple

def f(inputs: List[Tuple[int, int, List[Tuple[int, int, int, int]]]]) -> int:
    def solve(n, pw, items):
        dp = [[0] * (pw + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(pw + 1):
                dp[i][j] = dp[i - 1][j]
                if j >= items[i - 1][0]:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - items[i - 1][0]] + items[i - 1][1])
        return dp[n][pw]

    result = 0
    for n, pw, items in inputs:
        result += solve(n, pw, items)
    return result
